// ---- the arena's reset hook (docs/SPEC-TABLES.md §6) ----
//
// TableWorker::Alloc is a template and cannot name a member's Reset, so
// the arena reaches it through this overload set by argument-dependent
// lookup. It is how a node born in raw arena storage comes to hold the
// declared defaults without value-initialising the whole aggregate.

inline void TableReset( Node & value ) { NodeReset( value ); }
inline void TableReset( Ring & value ) { RingReset( value ); }
inline void TableReset( Rack & value ) { RackReset( value ); }
inline void TableReset( Tray & value ) { TrayReset( value ); }

// ---- pointer targets: allocation and resolution (docs/SPEC-TABLES.md §2) ----
//
// A reference resolves differently in the two forms, and the CONTEXT says
// which: in the arena it is an offset; in a region it is a self-relative
// delta, so the const deref below is one add and needs no base pointer.

// Node is a pointer target.
inline const Node * NodeAt( const TableRef & ref ) // the const form's hot path: one add, no base
{
    return ref.value != 0 ? (const Node *) ( (const uint8_t *) &ref + ref.value ) : NULL;
}
inline Node * NodeAt( TableRef & ref )
{
    return ref.value != 0 ? (Node *) ( (uint8_t *) &ref + ref.value ) : NULL;
}
inline const Node * NodeAt( const TableRegionCtx &, const TableRef & ref ) { return NodeAt( ref ); }
inline const Node * NodeAt( const TableArenaCtx & ctx, const TableRef & ref )
{
    return ref.value != 0 ? (const Node *) TableArenaAt( *ctx.arena, (uint32_t) ref.value ) : NULL;
}
// while the builder is mutable, resolve against the arena itself
inline Node * NodeAt( TableArena & arena, const TableRef & ref )
{
    return ref.value != 0 ? (Node *) TableArenaAt( arena, (uint32_t) ref.value ) : NULL;
}
inline const Node * NodeAt( const TableArena & arena, const TableRef & ref )
{
    return ref.value != 0 ? (const Node *) TableArenaAt( arena, (uint32_t) ref.value ) : NULL;
}
// allocate one Node in the arena; the slot holds the arena offset
inline Node * NodeEmplace( TableWorker & worker, TableRef & slot )
{
    TableSlot<Node> allocated = worker.Alloc<Node>();
    slot = allocated.ref;
    return allocated.ptr;
}

