// ---- Ring: the variable-length life (docs/SPEC-TABLES.md §2, §6, §9) ----
//
// MUTABLE: RingBuilder — allocate nodes, wire them together, then Lock.
// CONST:   one packed region, root at its base. Lock produces it and Load
//          produces it, so a locked structure and a loaded one are the
//          SAME representation with one view API. There is no unlock:
//          re-editing means loading the const form into a fresh builder.
// Ring is never held by value — a file-format-scale structure is a region
// and a root pointer, not a struct you copy.

struct RingBuilder
{
    TableArena arena;
    TableWorker main;      // the calling thread's allocation front
    TableRef root_ref;
    uint8_t * region = NULL; // the packed const form, produced by Lock()
    int64_t region_bytes = 0;

    // THE ALLOCATOR IS THE BUILDER'S, and everything this structure ever
    // allocates goes through it: the arena's segments, Lock's identity map,
    // the packed region, the wire walks' numbering, and the tool path's node
    // directory. Name your own and a profiler sees every byte under it.
    RingBuilder( TableAllocator allocator = TableDefaultAllocator() )
    {
        TableArenaInit( arena, allocator );
        main.arena = &arena;
        TableSlot<Ring> slot = main.Alloc<Ring>();
        root_ref = slot.ref;
    }
    ~RingBuilder() { TableArenaShutdown( arena ); arena.allocator.free( arena.allocator.context, region ); }
    RingBuilder( const RingBuilder & ) = delete;
    RingBuilder & operator=( const RingBuilder & ) = delete;

    // Alloc a node in THIS thread's slab: no lock, no atomic per node.
    // The result is usable both as the node pointer and as the reference
    // to store in a pointer field.
    template <typename T> TableSlot<T> Alloc() { return main.Alloc<T>(); }
    // a BYTE BUFFER's node of exactly `length` bytes (docs/SPEC-TABLES.md §2.5):
    // the bytes to write through, and the reference to store in a *bytes
    // or *string slot; a blob past a slab takes a span of its own
    TableBytesSlot AllocBytes( int64_t length ) { return main.AllocBytes( length ); }
    TableStringSlot AllocString( int64_t length ) { return main.AllocString( length ); }
    // one worker per thread; allocate on your own, and synchronize your own
    // writes to nodes another worker allocated
    TableWorker Worker() { TableWorker worker; worker.arena = &arena; return worker; }

    // GetRoot/AsConst, not Root/Const: a member function hides the type
    // name it shares, and `table Root` is this spec's own canonical
    // example. The checker refuses a table named after any member here,
    // so the remaining spellings cannot collide either.
    Ring * GetRoot() { return arena.locked ? NULL : (Ring *) TableArenaAt( arena, (uint32_t) root_ref.value ); }
    bool Locked() const { return arena.locked; }
    const Ring * AsConst() const { return (const Ring *) region; }
    const uint8_t * Region() const { return region; }
    int64_t RegionBytes() const { return region_bytes; }

    // Lock is ONE WAY and it is the compaction: the segmented arena becomes
    // one exact-packed region with zero slack, references rewritten
    // self-relative, and the mutable life released. Single-threaded: call
    // it after the workers have joined.
    bool Lock();
};

inline bool RingBuilder::Lock()
{
    if ( arena.locked ) { return region != NULL; }
    if ( root_ref.null() ) { return false; }
    TableArenaCtx ctx = { &arena };
    const Ring & root = *(const Ring *) TableArenaAt( arena, (uint32_t) root_ref.value );
    // The ROOT takes the map's first entry: it is packed at offset 0, and its
    // descent is open for the whole walk (docs/SPEC-TABLES.md §3.1).
    TablePackMap seen;
    TablePackMapInit( seen, arena.allocator );
    bool root_taken = false;
    int64_t root_slot = 0;
    int64_t below = -1;
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) != NULL )
    {
        below = RingPackMeasure( ctx, seen, root );
    }
    if ( below < 0 ) { TablePackMapShutdown( seen ); return false; } // a data cycle, named at the reference that closes it
    int64_t root_extent = RingExtent( ctx, root );
    if ( root_extent < 0 ) { TablePackMapShutdown( seen ); return false; } // the sort could not run
    int64_t total = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Ring ) ) + root_extent ) + below;
    // the AUTHORING path may allocate (§6.5), and it does so through the
    // builder's own pair. The region comes back ZEROED, which is the
    // allocator's contract: a packed region carries node padding.
    uint8_t * packed = (uint8_t *) arena.allocator.alloc( arena.allocator.context, total );
    if ( packed == NULL ) { TablePackMapShutdown( seen ); return false; }
    int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Ring ) ) + root_extent );
    Ring * destination = new ( packed ) Ring; // lifetime only: the Pack below memcpy's the whole node over it
    // The pack walk RE-DERIVES the same numbering rather than carrying the
    // measure's — nothing passes between them, which is what makes
    // `used == total` below a real check and not a tautology (§3.1). The
    // map keeps the capacity the measure paid for, so the second walk
    // rehashes nothing.
    TablePackMapReset( seen );
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) == NULL ||
         !RingPack( ctx, seen, root, *destination, packed, total, used ) || used != total )
    {
        TablePackMapShutdown( seen );
        arena.allocator.free( arena.allocator.context, packed );
        return false;
    }
    TablePackMapShutdown( seen );
    region = packed;
    region_bytes = total;
    arena.locked = true; // MONOTONIC: there is no unlock
    TableArenaShutdown( arena );
    return true;
}

// ---- Ring on the wire: the FLAT NODE TABLE (docs/SPEC-TABLES.md §3.1) ----
//
// A pointered save writes every reachable node ONCE, into a node table under
// the reserved id 0xFFFF, and a pointer field rides as a u32 INDEX into it
// under kind 17. No pointer edge is a nesting level, so a chain's length is
// not a depth and two references to one node are one node.

// RingNodeStorage: the region bytes one record commands, or -1 for a type id
// this build cannot name — which keeps its index and reads null. A BYTE
// BUFFER's record commands its header and its bytes (docs/SPEC-TABLES.md §2.5),
// which is the one answer the record's LENGTH decides, and a blob past the
// size cap answers kTableNodeRefused with its reason (§3.1, §6.5).
// A MAP'S ENTRIES RIDE IN THEIR HOLDER'S EXTENT (docs/SPEC-TABLES.md §2.8),
// so a record's storage is its type's PLUS N x sizeof( Entry ) at every
// depth, summed from the FRAMING: N is framing and not a value, and this
// reads no field. kTableNodeRefused is a wire whose N its L cannot carry.
inline int64_t RingNodeStorage( uint64_t type_id, int64_t length, TableRefuseReason & reason )
{
    (void) length; // no byte buffer below this root: every node's storage is its type's
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( (int64_t) sizeof( Node ) ); // Node
        default: break;
    }
    (void) reason; // no blob and no extent below this root: nothing here refuses
    return -1;
}

// RingNodePlace: start one record's node's lifetime in the storage pass one
// reserved for it, holding exactly the declared defaults — a byte buffer's
// header holds its length, and its bytes come in pass two.
inline void RingNodePlace( uint64_t type_id, uint8_t * at, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: { Node * node = new ( at ) Node; NodeReset( *node ); break; } // Node
        default: break;
    }
}

// RingNodeRecordBytes: one record's OWN storage, before the extent its maps
// take (docs/SPEC-TABLES.md §2.8) — where a node's extent begins.
inline int64_t RingNodeRecordBytes( uint64_t type_id )
{
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( (int64_t) sizeof( Node ) ); // Node
        default: break;
    }
    return 0;
}

// RingNodeAlloc: the TOOL's path — one record's node in the builder's arena.
// Zero is the arena's null, and it is also what a type id this build cannot
// name answers.
inline uint32_t RingNodeAlloc( uint64_t type_id, TableWorker & worker, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return (uint32_t) worker.Alloc<Node>().ref.value; // Node
        default: break;
    }
    return 0;
}

// RingNodeBody: PASS TWO's half — decode one record's body into the storage it
// already owns.
inline void RingNodeBody( uint64_t type_id, TableReader & r, const TableNodeMap & nodes, uint8_t * at )
{
    // the node's own EXTENT, where its lists' and maps' arrays are carved
    // from, PRE-ORDER as the bodies decode (docs/SPEC-TABLES.md §2.8, §2.9).
    // The tool's path carries a worker instead: there the arrays are the
    // arena's.
    TableExtentCarve carve;
    carve.worker = nodes.worker;
    if ( carve.worker == NULL )
    {
        TableRefuseReason reason = count_over_length; // pass one already refused what this could refuse
        const int64_t storage = RingNodeStorage( type_id, r.size, reason );
        const int64_t record = storage > 0 ? RingNodeRecordBytes( type_id ) : 0;
        carve.at = at + record;
        carve.left = storage > record ? storage - record : 0;
    }
    nodes.carve = &carve;
    (void) nodes; // every node this root can name is a FIXED table
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: NodeLoadBody( r, *(Node *) at ); break; // Node
        default: break;
    }
    nodes.carve = NULL; // the cursor is ONE node's, and this node's body is done
}

// RingNodeMessageStorage: the region bytes one record commands on the message
// wire, or -1 for a type id this build cannot name. A table's is its own
// storage plus the extent its maps take; a byte buffer's is its header and
// its bytes, which is the one answer the record's LENGTH decides.
inline int64_t RingNodeMessageStorage( uint64_t type_id, int64_t extent, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Node ) ) + extent ); // Node
        default: break;
    }
    return -1;
}

// RingNodeMessageExtent: step over one TABLE record's body, tallying the extent
// its maps take where its type has any (§2.8). A type this build cannot
// name is stepped over by its announced shapes and takes no extent.
inline bool RingNodeMessageExtent( uint64_t type_id, TableBitReader & r, const TableVocabulary & vocabulary, int64_t index_bits, int64_t & extent )
{
    extent = 0;
    (void) type_id; // no map below any node this root can name
    return TableMessageSkipBody( r, vocabulary, index_bits );
}

// RingNodeMessageBody: PASS TWO's half, which decodes one record's body into
// storage it already owns, its map entries carved from its own extent.
inline bool RingNodeMessageBody( uint64_t type_id, TableBitReader & r, const TableVocabulary & vocabulary, TableReport * report, const TableNodeMap & nodes, int64_t index_bits, uint8_t * at )
{
    TableExtentCarve carve;
    carve.at = at + RingNodeRecordBytes( type_id );
    carve.left = 0;
    {
        // the extent this record was placed with, re-read from the framing
        TableBitReader walk = r;
        int64_t extent = 0;
        if ( !RingNodeMessageExtent( type_id, walk, vocabulary, index_bits, extent ) ) { report->malformed = true; return false; }
        carve.left = extent;
    }
    TableExtentCarve * const outer = nodes.carve;
    nodes.carve = &carve;
    (void) nodes; (void) index_bits; // every node this root can name is a FIXED table
    bool ok = false;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: ok = NodeLoadMessageBody( r, vocabulary, report, index_bits, *(Node *) at ); break; // Node
        // a record this dispatch cannot name never reaches here: pass one left it absent
        default: report->malformed = true; break;
    }
    nodes.carve = outer;
    return ok;
}

// The numbering both wire walks derive, and NEITHER CARRIES THE OTHER'S: the
// root takes index 1 and its entry stays open for the whole walk, so a
// reference back at it is the cycle it is (§3.1).
template <typename Ctx>
inline bool RingNumberFrom( const Ctx & ctx, TableNumbering & numbering, const Ring & root )
{
    bool taken = false;
    int64_t slot = 0;
    if ( TablePackMapReach( numbering.seen, (const void *) &root, (int64_t) kTableNodeIndexRoot, taken, slot ) == NULL ) { return false; }
    return RingNumber( ctx, numbering, root );
}

template <typename Ctx>
inline int64_t RingMeasureWire( const Ctx & ctx, const Ring & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bytes = -1;
    if ( RingNumberFrom( ctx, numbering, root ) )
    {
        TableIds ids;
        bytes = RingMeasureBody( ctx, numbering, ids, root );
        if ( bytes >= 0 )
        {
            const int64_t table = TableNodeTableMeasure( ctx, ids, numbering );
            // the FORM BYTE, the ROOT BODY — its own fields, the node table
            // and the terminator — and the ID TABLE (docs/SPEC-TABLES.md §3)
            bytes = table < 0 || ids.overflow ? -1 : 1 + bytes + table + TableIdsBytes( ids );
        }
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

template <typename Ctx>
inline int64_t RingSaveWire( const Ctx & ctx, const Ring & root, uint8_t * buffer, int64_t capacity, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    if ( !RingNumberFrom( ctx, numbering, root ) ) { TableNumberingShutdown( numbering ); return -1; }
    TableWriter w( buffer, capacity );
    TableIds ids;
    w.put8( kTableWireForm ); // the FORM BYTE is the whole header (§3)
    // the root's own fields, then the node table's field, then the
    // terminator: a reader that gives up inside the table has already
    // decoded the ROOT'S OWN FIELDS (§3.1)
    bool ok = RingSaveBodyFields( ctx, numbering, w, ids, root ) && TableNodeTableSave( ctx, w, ids, numbering );
    TableNumberingShutdown( numbering );
    if ( !ok || ids.overflow ) { return -1; }
    w.put8( 0 ); // the ZERO REFERENCE that ends the root body
    TableIdsWrite( w, ids );
    if ( w.overflow ) { return -1; } // the caller's buffer was too small
    return w.offset; // == RingMeasure( root )
}

inline int64_t RingMeasure( const Ring * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return RingMeasureWire( ctx, *root, allocator );
}

inline int64_t RingSave( const Ring * root, uint8_t * buffer, int64_t capacity, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return RingSaveWire( ctx, *root, buffer, capacity, allocator );
}

inline int64_t RingMeasure( const RingBuilder & builder )
{
    if ( builder.region != NULL ) { return RingMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return RingMeasureWire( ctx, *(const Ring *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline int64_t RingSave( const RingBuilder & builder, uint8_t * buffer, int64_t capacity )
{
    if ( builder.region != NULL ) { return RingSave( builder.AsConst(), buffer, capacity, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return RingSaveWire( ctx, *(const Ring *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), buffer, capacity, builder.arena.allocator );
}

// ---- Ring on the MESSAGE wire: the batch over a region (docs/SPEC-TABLES.md §3.3) ----

// RingMessageBodyBits: one root body's bits at bit position `at` of the batch,
// with the numbering derived from the graph, the node table FIRST, then the
// fields, then the zero reference. Measure derives the numbering and save
// derives the same one, and nothing passes between them (§3.1).
template <typename Ctx>
inline int64_t RingMessageBodyBits( const Ctx & ctx, const Ring & root, int64_t at, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bits = -1;
    if ( RingNumberFrom( ctx, numbering, root ) )
    {
        const int64_t index_bits = TableBitsRequired( 0, numbering.count + 1 );
        const int64_t table = TableMessageNodeTableMeasure( ctx, numbering, index_bits, at );
        if ( table >= 0 )
        {
            const int64_t body = RingMeasureMessageBody( ctx, numbering, index_bits, at + table, root );
            bits = body < 0 ? -1 : table + body;
        }
    }
    TableNumberingShutdown( numbering );
    return bits;
}

template <typename Ctx>
inline bool RingMessageBodySave( const Ctx & ctx, const Ring & root, TableBitWriter & w, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    bool ok = false;
    if ( RingNumberFrom( ctx, numbering, root ) )
    {
        const int64_t index_bits = TableBitsRequired( 0, numbering.count + 1 );
        ok = TableMessageNodeTableSave( ctx, numbering, index_bits, w ) && RingSaveMessageBody( ctx, numbering, index_bits, w, root );
    }
    TableNumberingShutdown( numbering );
    return ok && !w.overflow;
}

// THE PRIMITIVE IS A BATCH (§3.3): a number of ROOTS in one buffer, one count
// and one continuous bit stream, each body carrying its own numbering. A
// root is a locked region's, `builder.AsConst()`, or a loaded one's. M above
// 256 is a refusal by name, batch_too_large, with nothing written.
inline int64_t RingMeasureMessages( const Ring * const * roots, int64_t count, TableReport * report, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( roots == NULL || count < 1 ) { return -1; }
    if ( count > kTableMessageBatchMax ) { TableMessageRefuseBatch( report ); return -1; }
    TableRegionCtx ctx;
    int64_t bits = 8; // the body count
    for ( int64_t i = 0; i < count; i++ )
    {
        if ( roots[i] == NULL ) { return -1; }
        const int64_t body = RingMessageBodyBits( ctx, *roots[i], bits, allocator );
        if ( body < 0 ) { return -1; }
        bits += body;
    }
    return 1 + ( bits + 7 ) / 8;
}

inline int64_t RingSaveMessages( const Ring * const * roots, int64_t count, uint8_t * buffer, int64_t capacity, TableReport * report, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( roots == NULL || count < 1 ) { return -1; }
    if ( count > kTableMessageBatchMax ) { TableMessageRefuseBatch( report ); return -1; }
    TableMessageBatch batch;
    if ( !TableMessageBatchBegin( batch, buffer, capacity, count ) ) { return -1; }
    TableRegionCtx ctx;
    for ( int64_t i = 0; i < count; i++ )
    {
        if ( roots[i] == NULL || !RingMessageBodySave( ctx, *roots[i], batch.w, allocator ) ) { return -1; }
        batch.written++;
    }
    return TableMessageBatchEnd( batch ); // == RingMeasureMessages( roots, count, report, allocator )
}

// RingMessageRecordScan: one node record's type id and the extent its maps
// take, or a blob's length, the reader left after the record. A type id
// reference of 0, one past E, or one naming anything but a kind-0 entry is
// damage, as §3.1 and §3.3 say.
inline bool RingMessageRecordScan( TableBitReader & r, const TableVocabulary & vocabulary, int64_t index_bits, uint64_t & type_id, int64_t & extent, int64_t & length )
{
    uint64_t type_ref = 0;
    if ( !r.get( type_ref, vocabulary.ref_bits ) ) { return false; }
    TableMessageEntry type_entry;
    if ( !TableMessageNameEntry( vocabulary, type_ref, type_entry ) ) { return false; }
    type_id = type_entry.id;
    extent = 0;
    length = 0;
    if ( type_id == kTableBytesTypeId || type_id == kTableStringTypeId )
    {
        // A BLOB RECORD CARRIES A LENGTH AT THIRTY-TWO RAW BITS, then ALIGNS,
        // then the bytes verbatim (§3.3)
        uint64_t n = 0;
        if ( !r.get( n, 32 ) || !r.align() || !r.skip( (int64_t) n * 8 ) ) { return false; }
        length = (int64_t) n;
        return true;
    }
    return RingNodeMessageExtent( type_id, r, vocabulary, index_bits, extent );
}

// RingMessageBodyStorage: one body's node count and data bytes from the FRAMING
// alone, the reader left at the next body. The node table is walked record
// by record, a table record's body stepped over by its announced shapes and
// a blob's by its length, then the root's own fields. False is a numbering
// that could not be sized; `complete` false is a ROOT body whose own framing
// gave out, which the load meets as damage inside this body after the
// bodies before it were delivered, so the batch is sized through this body
// and no further (§3.3).
inline bool RingMessageBodyStorage( TableBitReader & r, const TableVocabulary & vocabulary, int64_t & records, int64_t & data, bool & complete )
{
    complete = true;
    records = 0;
    data = 0;
    int64_t count = 0;
    if ( !TableMessageNodeTableOpen( r, vocabulary, count ) ) { return false; }
    const int64_t index_bits = TableBitsRequired( 0, count + 1 );
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_id = 0;
        int64_t extent = 0, length = 0;
        if ( !RingMessageRecordScan( r, vocabulary, index_bits, type_id, extent, length ) ) { return false; }
        const int64_t storage = RingNodeMessageStorage( type_id, extent, length );
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
        records++;
    }
    int64_t root_extent = 0;
    if ( !RingMessageExtent( r, vocabulary, index_bits, root_extent ) ) { complete = false; }
    data += TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Ring ) ) + root_extent );
    return true;
}

// RingLoadMeasure's MESSAGE overload: the exact region bytes ONE BATCH needs,
// which is one measurement, one allocation and one bounds check for however
// many bodies ride (§3.3, §6.5). It is a scan by the announced shapes and
// reads no field value. The answer is the data bytes plus the attribution,
// one node directory a body, and -1 for a wire it cannot size: no vocabulary,
// another form, or framing that gives out.
inline int64_t RingLoadMeasure( const TableVocabulary & vocabulary, const uint8_t * buffer, int64_t bytes, int64_t * attribution_bytes = NULL )
{
    TableReport ignored;
    TableMessageBatchReader br;
    const int64_t bodies = TableMessageBatchOpen( br, vocabulary, buffer, bytes, &ignored );
    if ( bodies < 0 ) { return -1; }
    int64_t data = 0, attribution = 0;
    for ( int64_t b = 0; b < bodies; b++ )
    {
        int64_t records = 0, body_data = 0;
        bool complete = true;
        if ( !RingMessageBodyStorage( br.r, vocabulary, records, body_data, complete ) ) { return -1; }
        data += body_data;
        attribution += ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
        if ( !complete ) { break; } // damage inside this body: the load delivers the ones before it
    }
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// RingLoadMessageBodyInto: one body of a batch into the region at `used`. Its
// chunk is the node DIRECTORY, then the records in wire order, then the root
// and the extent its maps take, so every offset a pass needs is known when
// the pass reaches it. PASS ONE fills the numbering from the framing and
// places every node; PASS TWO decodes each record's body into the storage it
// owns; the ROOT's own body decodes last, so every index it carries resolves
// against a numbering already known whole.
inline bool RingLoadMessageBodyInto( TableBitReader & r, const TableVocabulary & vocabulary, TableReport * out, uint8_t * region, int64_t region_bytes, int64_t & used, const Ring * & root_out )
{
    // the node table opens the body, or the body has none
    int64_t count = 0;
    if ( !TableMessageNodeTableOpen( r, vocabulary, count ) ) { out->malformed = true; return false; }
    const int64_t directory_bytes = ( count + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( used + directory_bytes > region_bytes ) { out->malformed = true; return false; }
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + used );
    used += directory_bytes;
    const int64_t index_bits = TableBitsRequired( 0, count + 1 );
    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = directory;
    nodes.count = count + 1;
    nodes.good = false;

    // PASS ONE: the numbering from the framing, every node placed, no body read
    const int64_t records_start = r.offset;
    int32_t unknown_records = 0;
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_id = 0;
        int64_t extent = 0, length = 0;
        if ( !RingMessageRecordScan( r, vocabulary, index_bits, type_id, extent, length ) ) { out->malformed = true; return false; }
        const int64_t storage = RingNodeMessageStorage( type_id, extent, length );
        directory[k + 1].type_id = type_id;
        if ( storage <= 0 )
        {
            // a record whose type id this build cannot name KEEPS ITS INDEX, is
            // counted once here and not once per pointer, and every reference
            // to it reads null (§3.1)
            unknown_records++;
            directory[k + 1].offset = kTableNodeAbsent;
            continue;
        }
        if ( used + storage > region_bytes ) { out->malformed = true; return false; }
        directory[k + 1].offset = (uint64_t) used;
        RingNodePlace( type_id, region + used, length );
        used += storage;
    }
    const int64_t fields_start = r.offset;
    int64_t root_extent = 0;
    {
        TableBitReader walk = r;
        if ( !RingMessageExtent( walk, vocabulary, index_bits, root_extent ) ) { out->malformed = true; return false; }
    }
    const int64_t root_bytes = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Ring ) ) + root_extent );
    if ( used + root_bytes > region_bytes ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) used;
    directory[0].type_id = 0xdcea4d2bfa11ceebull;
    Ring * root = new ( region + used ) Ring; // lifetime only: LoadMessageBody's first act is RingReset
    RingReset( *root );
    root_out = root;
    TableExtentCarve root_carve;
    root_carve.at = region + used + TableAlignUp64( (int64_t) sizeof( Ring ) );
    root_carve.left = root_extent;
    used += root_bytes;
    nodes.good = true;
    out->unknown += unknown_records;

    // PASS TWO: each record's body into its own storage, in wire order
    r.offset = records_start;
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_ref = 0;
        if ( !r.get( type_ref, vocabulary.ref_bits ) ) { out->malformed = true; return false; }
        const uint64_t type_id = directory[k + 1].type_id;
        if ( type_id == kTableBytesTypeId || type_id == kTableStringTypeId )
        {
            uint64_t length = 0;
            if ( !r.get( length, 32 ) || !r.align() || !r.has( (int64_t) length * 8 ) ) { out->malformed = true; return false; }
            if ( directory[k + 1].offset != kTableNodeAbsent && length > 0 ) { memcpy( region + directory[k + 1].offset + kTableBlobHeader, r.buffer + r.offset / 8, (size_t) length ); }
            r.offset += (int64_t) length * 8;
            continue;
        }
        if ( directory[k + 1].offset == kTableNodeAbsent )
        {
            if ( !TableMessageSkipBody( r, vocabulary, index_bits ) ) { out->malformed = true; return false; }
            continue;
        }
        if ( !RingNodeMessageBody( type_id, r, vocabulary, out, nodes, index_bits, region + directory[k + 1].offset ) ) { return false; }
    }
    if ( r.offset != fields_start ) { out->malformed = true; return false; } // the two passes disagree about the table's extent

    // and the ROOT's own body last
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    return RingLoadMessageBody( r, vocabulary, out, nodes, index_bits, *root );
}

// RingLoadMessages: decode a BATCH into the caller's exact-sized region and
// write each body's root into `roots`. `count` is IN and OUT: the storage the
// caller has room for, then what it got. M above the capacity is a refusal
// by name with count holding the wire's M; damage inside body k delivers
// bodies 1 to k - 1 and count says k - 1 (§3.3). LOAD IS A SCAN: it follows
// no reference, so there is no depth cap and no visited set. NULL roots
// beyond count are not bodies.
inline bool RingLoadMessages( const Ring ** roots, int64_t * count, uint8_t * region, int64_t region_bytes, const TableVocabulary & vocabulary, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    if ( roots == NULL || count == NULL ) { out->malformed = true; return false; }
    const int64_t capacity = *count;
    *count = 0;
    TableMessageBatchReader br;
    const int64_t bodies = TableMessageBatchOpen( br, vocabulary, buffer, bytes, out );
    if ( bodies < 0 ) { return false; }
    if ( bodies > capacity ) { *count = bodies; TableMessageRefuseBatch( out ); return false; }
    if ( region == NULL || region_bytes < 0 || ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return false; }
    memset( region, 0, (size_t) region_bytes );
    int64_t used = 0;
    for ( int64_t b = 0; b < bodies; b++ )
    {
        roots[b] = NULL;
        if ( !RingLoadMessageBodyInto( br.r, vocabulary, out, region, region_bytes, used, roots[b] ) ) { *count = b; return false; }
        br.remaining--;
    }
    *count = bodies;
    return TableMessageBatchClose( br );
}

// RingLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t RingLoadMeasure( const uint8_t * wire_file, int64_t wire_file_bytes, int64_t * attribution_bytes = NULL, TableRefuseReason * reason_out = NULL )
{
    TableReport ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    // a FORM BYTE this build does not carry is refused by name (§3, §6.5);
    // a trailer that cannot be read whole is damage and names no reason
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict == TableOpenRefused ) { if ( reason_out != NULL ) { *reason_out = unknown_form; } return -1; }
    if ( verdict != TableOpenOk ) { return -1; }
    // ANY BYTE BETWEEN THE ROOT'S TERMINATOR AND THE TABLE'S FIRST ENTRY
    // IS MALFORMED (docs/SPEC-TABLES.md §3): the two ends of the file have
    // met, nothing is decoded, and no region is sized from it.
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) ) { return -1; }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    TableRefuseReason reason = count_over_length;
    int64_t root_extent = 0;
    if ( !RingWireExtent( wire, wire_bytes, root_extent, &ids_table, reason ) ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Ring ) ) + root_extent );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = RingNodeStorage( type_id, length, reason );
        if ( storage == kTableNodeRefused ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; } // an N the record's framing cannot carry, or a blob past the cap (§2.8, §2.9, §3.1)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// RingLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Ring * RingLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, then the trailer, and only then a body:
    // a file that is both a newer form and damaged is a REFUSAL and never
    // damage (docs/SPEC-TABLES.md §3).
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; if ( wire_file_bytes > 0 && wire_file[0] == kTableWireMessageForm ) { out->reason = message_form_as_file; } else { out->reason = newer_form; } }
        return NULL;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return NULL;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Ring ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    TableRefuseReason reason = count_over_length; // LoadMeasure is where a caller reads it; a Load past a refusal is malformed
    int64_t root_extent = 0;
    if ( !RingWireExtent( wire, wire_bytes, root_extent, &ids_table, reason ) ) { out->malformed = true; return NULL; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Ring ) ) + root_extent );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = RingNodeStorage( type_id, length, reason );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0xdcea4d2bfa11ceebull;
    Ring * root = new ( region ) Ring; // lifetime only: LoadBody's first act is RingReset
    RingReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Ring ) ) + root_extent );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = RingNodeStorage( type_id, length, reason );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                RingNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                RingNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableExtentCarve root_carve;
    root_carve.at = region + TableAlignUp64( (int64_t) sizeof( Ring ) );
    root_carve.left = root_extent;
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    RingLoadBody( r, nodes, *root );
    return root;
}

// RingLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool RingLoadBuilder( RingBuilder & builder, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; }
        return false;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return false;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    Ring * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0xdcea4d2bfa11ceebull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    nodes.worker = &builder.main; // and a map's entries and a list's elements are the arena's, not a node extent's (§2.8, §2.9)
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = RingNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                RingNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableExtentCarve root_carve;
    root_carve.worker = &builder.main;
    nodes.carve = &root_carve;
    bool ok = RingLoadBody( r, nodes, *root );
    // A COUNT ABOVE THE int32 CAP is this path's refusal (docs/SPEC-TABLES.md
    // §2.9): the partial builder is the caller's to discard, and the report
    // holds what it held when the count was met
    ok = ok && !nodes.refused;
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- Rack: the variable-length life (docs/SPEC-TABLES.md §2, §6, §9) ----
//
// MUTABLE: RackBuilder — allocate nodes, wire them together, then Lock.
// CONST:   one packed region, root at its base. Lock produces it and Load
//          produces it, so a locked structure and a loaded one are the
//          SAME representation with one view API. There is no unlock:
//          re-editing means loading the const form into a fresh builder.
// Rack is never held by value — a file-format-scale structure is a region
// and a root pointer, not a struct you copy.

struct RackBuilder
{
    TableArena arena;
    TableWorker main;      // the calling thread's allocation front
    TableRef root_ref;
    uint8_t * region = NULL; // the packed const form, produced by Lock()
    int64_t region_bytes = 0;

    // THE ALLOCATOR IS THE BUILDER'S, and everything this structure ever
    // allocates goes through it: the arena's segments, Lock's identity map,
    // the packed region, the wire walks' numbering, and the tool path's node
    // directory. Name your own and a profiler sees every byte under it.
    RackBuilder( TableAllocator allocator = TableDefaultAllocator() )
    {
        TableArenaInit( arena, allocator );
        main.arena = &arena;
        TableSlot<Rack> slot = main.Alloc<Rack>();
        root_ref = slot.ref;
    }
    ~RackBuilder() { TableArenaShutdown( arena ); arena.allocator.free( arena.allocator.context, region ); }
    RackBuilder( const RackBuilder & ) = delete;
    RackBuilder & operator=( const RackBuilder & ) = delete;

    // Alloc a node in THIS thread's slab: no lock, no atomic per node.
    // The result is usable both as the node pointer and as the reference
    // to store in a pointer field.
    template <typename T> TableSlot<T> Alloc() { return main.Alloc<T>(); }
    // a BYTE BUFFER's node of exactly `length` bytes (docs/SPEC-TABLES.md §2.5):
    // the bytes to write through, and the reference to store in a *bytes
    // or *string slot; a blob past a slab takes a span of its own
    TableBytesSlot AllocBytes( int64_t length ) { return main.AllocBytes( length ); }
    TableStringSlot AllocString( int64_t length ) { return main.AllocString( length ); }
    // one worker per thread; allocate on your own, and synchronize your own
    // writes to nodes another worker allocated
    TableWorker Worker() { TableWorker worker; worker.arena = &arena; return worker; }

    // GetRoot/AsConst, not Root/Const: a member function hides the type
    // name it shares, and `table Root` is this spec's own canonical
    // example. The checker refuses a table named after any member here,
    // so the remaining spellings cannot collide either.
    Rack * GetRoot() { return arena.locked ? NULL : (Rack *) TableArenaAt( arena, (uint32_t) root_ref.value ); }
    bool Locked() const { return arena.locked; }
    const Rack * AsConst() const { return (const Rack *) region; }
    const uint8_t * Region() const { return region; }
    int64_t RegionBytes() const { return region_bytes; }

    // Lock is ONE WAY and it is the compaction: the segmented arena becomes
    // one exact-packed region with zero slack, references rewritten
    // self-relative, and the mutable life released. Single-threaded: call
    // it after the workers have joined.
    bool Lock();
};

inline bool RackBuilder::Lock()
{
    if ( arena.locked ) { return region != NULL; }
    if ( root_ref.null() ) { return false; }
    TableArenaCtx ctx = { &arena };
    const Rack & root = *(const Rack *) TableArenaAt( arena, (uint32_t) root_ref.value );
    // The ROOT takes the map's first entry: it is packed at offset 0, and its
    // descent is open for the whole walk (docs/SPEC-TABLES.md §3.1).
    TablePackMap seen;
    TablePackMapInit( seen, arena.allocator );
    bool root_taken = false;
    int64_t root_slot = 0;
    int64_t below = -1;
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) != NULL )
    {
        below = RackPackMeasure( ctx, seen, root );
    }
    if ( below < 0 ) { TablePackMapShutdown( seen ); return false; } // a data cycle, named at the reference that closes it
    int64_t root_extent = RackExtent( ctx, root );
    if ( root_extent < 0 ) { TablePackMapShutdown( seen ); return false; } // the sort could not run
    int64_t total = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Rack ) ) + root_extent ) + below;
    // the AUTHORING path may allocate (§6.5), and it does so through the
    // builder's own pair. The region comes back ZEROED, which is the
    // allocator's contract: a packed region carries node padding.
    uint8_t * packed = (uint8_t *) arena.allocator.alloc( arena.allocator.context, total );
    if ( packed == NULL ) { TablePackMapShutdown( seen ); return false; }
    int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Rack ) ) + root_extent );
    Rack * destination = new ( packed ) Rack; // lifetime only: the Pack below memcpy's the whole node over it
    // The pack walk RE-DERIVES the same numbering rather than carrying the
    // measure's — nothing passes between them, which is what makes
    // `used == total` below a real check and not a tautology (§3.1). The
    // map keeps the capacity the measure paid for, so the second walk
    // rehashes nothing.
    TablePackMapReset( seen );
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) == NULL ||
         !RackPack( ctx, seen, root, *destination, packed, total, used ) || used != total )
    {
        TablePackMapShutdown( seen );
        arena.allocator.free( arena.allocator.context, packed );
        return false;
    }
    TablePackMapShutdown( seen );
    region = packed;
    region_bytes = total;
    arena.locked = true; // MONOTONIC: there is no unlock
    TableArenaShutdown( arena );
    return true;
}

// ---- Rack on the wire: the FLAT NODE TABLE (docs/SPEC-TABLES.md §3.1) ----
//
// A pointered save writes every reachable node ONCE, into a node table under
// the reserved id 0xFFFF, and a pointer field rides as a u32 INDEX into it
// under kind 17. No pointer edge is a nesting level, so a chain's length is
// not a depth and two references to one node are one node.

// RackNodeStorage: the region bytes one record commands, or -1 for a type id
// this build cannot name — which keeps its index and reads null. A BYTE
// BUFFER's record commands its header and its bytes (docs/SPEC-TABLES.md §2.5),
// which is the one answer the record's LENGTH decides, and a blob past the
// size cap answers kTableNodeRefused with its reason (§3.1, §6.5).
// A MAP'S ENTRIES RIDE IN THEIR HOLDER'S EXTENT (docs/SPEC-TABLES.md §2.8),
// so a record's storage is its type's PLUS N x sizeof( Entry ) at every
// depth, summed from the FRAMING: N is framing and not a value, and this
// reads no field. kTableNodeRefused is a wire whose N its L cannot carry.
inline int64_t RackNodeStorage( uint64_t type_id, int64_t length, TableRefuseReason & reason )
{
    (void) length; // no byte buffer below this root: every node's storage is its type's
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( (int64_t) sizeof( Node ) ); // Node
        default: break;
    }
    (void) reason; // no blob and no extent below this root: nothing here refuses
    return -1;
}

// RackNodePlace: start one record's node's lifetime in the storage pass one
// reserved for it, holding exactly the declared defaults — a byte buffer's
// header holds its length, and its bytes come in pass two.
inline void RackNodePlace( uint64_t type_id, uint8_t * at, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: { Node * node = new ( at ) Node; NodeReset( *node ); break; } // Node
        default: break;
    }
}

// RackNodeRecordBytes: one record's OWN storage, before the extent its maps
// take (docs/SPEC-TABLES.md §2.8) — where a node's extent begins.
inline int64_t RackNodeRecordBytes( uint64_t type_id )
{
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( (int64_t) sizeof( Node ) ); // Node
        default: break;
    }
    return 0;
}

// RackNodeAlloc: the TOOL's path — one record's node in the builder's arena.
// Zero is the arena's null, and it is also what a type id this build cannot
// name answers.
inline uint32_t RackNodeAlloc( uint64_t type_id, TableWorker & worker, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return (uint32_t) worker.Alloc<Node>().ref.value; // Node
        default: break;
    }
    return 0;
}

// RackNodeBody: PASS TWO's half — decode one record's body into the storage it
// already owns.
inline void RackNodeBody( uint64_t type_id, TableReader & r, const TableNodeMap & nodes, uint8_t * at )
{
    // the node's own EXTENT, where its lists' and maps' arrays are carved
    // from, PRE-ORDER as the bodies decode (docs/SPEC-TABLES.md §2.8, §2.9).
    // The tool's path carries a worker instead: there the arrays are the
    // arena's.
    TableExtentCarve carve;
    carve.worker = nodes.worker;
    if ( carve.worker == NULL )
    {
        TableRefuseReason reason = count_over_length; // pass one already refused what this could refuse
        const int64_t storage = RackNodeStorage( type_id, r.size, reason );
        const int64_t record = storage > 0 ? RackNodeRecordBytes( type_id ) : 0;
        carve.at = at + record;
        carve.left = storage > record ? storage - record : 0;
    }
    nodes.carve = &carve;
    (void) nodes; // every node this root can name is a FIXED table
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: NodeLoadBody( r, *(Node *) at ); break; // Node
        default: break;
    }
    nodes.carve = NULL; // the cursor is ONE node's, and this node's body is done
}

// RackNodeMessageStorage: the region bytes one record commands on the message
// wire, or -1 for a type id this build cannot name. A table's is its own
// storage plus the extent its maps take; a byte buffer's is its header and
// its bytes, which is the one answer the record's LENGTH decides.
inline int64_t RackNodeMessageStorage( uint64_t type_id, int64_t extent, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Node ) ) + extent ); // Node
        default: break;
    }
    return -1;
}

// RackNodeMessageExtent: step over one TABLE record's body, tallying the extent
// its maps take where its type has any (§2.8). A type this build cannot
// name is stepped over by its announced shapes and takes no extent.
inline bool RackNodeMessageExtent( uint64_t type_id, TableBitReader & r, const TableVocabulary & vocabulary, int64_t index_bits, int64_t & extent )
{
    extent = 0;
    (void) type_id; // no map below any node this root can name
    return TableMessageSkipBody( r, vocabulary, index_bits );
}

// RackNodeMessageBody: PASS TWO's half, which decodes one record's body into
// storage it already owns, its map entries carved from its own extent.
inline bool RackNodeMessageBody( uint64_t type_id, TableBitReader & r, const TableVocabulary & vocabulary, TableReport * report, const TableNodeMap & nodes, int64_t index_bits, uint8_t * at )
{
    TableExtentCarve carve;
    carve.at = at + RackNodeRecordBytes( type_id );
    carve.left = 0;
    {
        // the extent this record was placed with, re-read from the framing
        TableBitReader walk = r;
        int64_t extent = 0;
        if ( !RackNodeMessageExtent( type_id, walk, vocabulary, index_bits, extent ) ) { report->malformed = true; return false; }
        carve.left = extent;
    }
    TableExtentCarve * const outer = nodes.carve;
    nodes.carve = &carve;
    (void) nodes; (void) index_bits; // every node this root can name is a FIXED table
    bool ok = false;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: ok = NodeLoadMessageBody( r, vocabulary, report, index_bits, *(Node *) at ); break; // Node
        // a record this dispatch cannot name never reaches here: pass one left it absent
        default: report->malformed = true; break;
    }
    nodes.carve = outer;
    return ok;
}

// The numbering both wire walks derive, and NEITHER CARRIES THE OTHER'S: the
// root takes index 1 and its entry stays open for the whole walk, so a
// reference back at it is the cycle it is (§3.1).
template <typename Ctx>
inline bool RackNumberFrom( const Ctx & ctx, TableNumbering & numbering, const Rack & root )
{
    bool taken = false;
    int64_t slot = 0;
    if ( TablePackMapReach( numbering.seen, (const void *) &root, (int64_t) kTableNodeIndexRoot, taken, slot ) == NULL ) { return false; }
    return RackNumber( ctx, numbering, root );
}

template <typename Ctx>
inline int64_t RackMeasureWire( const Ctx & ctx, const Rack & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bytes = -1;
    if ( RackNumberFrom( ctx, numbering, root ) )
    {
        TableIds ids;
        bytes = RackMeasureBody( ctx, numbering, ids, root );
        if ( bytes >= 0 )
        {
            const int64_t table = TableNodeTableMeasure( ctx, ids, numbering );
            // the FORM BYTE, the ROOT BODY — its own fields, the node table
            // and the terminator — and the ID TABLE (docs/SPEC-TABLES.md §3)
            bytes = table < 0 || ids.overflow ? -1 : 1 + bytes + table + TableIdsBytes( ids );
        }
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

template <typename Ctx>
inline int64_t RackSaveWire( const Ctx & ctx, const Rack & root, uint8_t * buffer, int64_t capacity, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    if ( !RackNumberFrom( ctx, numbering, root ) ) { TableNumberingShutdown( numbering ); return -1; }
    TableWriter w( buffer, capacity );
    TableIds ids;
    w.put8( kTableWireForm ); // the FORM BYTE is the whole header (§3)
    // the root's own fields, then the node table's field, then the
    // terminator: a reader that gives up inside the table has already
    // decoded the ROOT'S OWN FIELDS (§3.1)
    bool ok = RackSaveBodyFields( ctx, numbering, w, ids, root ) && TableNodeTableSave( ctx, w, ids, numbering );
    TableNumberingShutdown( numbering );
    if ( !ok || ids.overflow ) { return -1; }
    w.put8( 0 ); // the ZERO REFERENCE that ends the root body
    TableIdsWrite( w, ids );
    if ( w.overflow ) { return -1; } // the caller's buffer was too small
    return w.offset; // == RackMeasure( root )
}

inline int64_t RackMeasure( const Rack * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return RackMeasureWire( ctx, *root, allocator );
}

inline int64_t RackSave( const Rack * root, uint8_t * buffer, int64_t capacity, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return RackSaveWire( ctx, *root, buffer, capacity, allocator );
}

inline int64_t RackMeasure( const RackBuilder & builder )
{
    if ( builder.region != NULL ) { return RackMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return RackMeasureWire( ctx, *(const Rack *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline int64_t RackSave( const RackBuilder & builder, uint8_t * buffer, int64_t capacity )
{
    if ( builder.region != NULL ) { return RackSave( builder.AsConst(), buffer, capacity, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return RackSaveWire( ctx, *(const Rack *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), buffer, capacity, builder.arena.allocator );
}

// ---- Rack on the MESSAGE wire: the batch over a region (docs/SPEC-TABLES.md §3.3) ----

// RackMessageBodyBits: one root body's bits at bit position `at` of the batch,
// with the numbering derived from the graph, the node table FIRST, then the
// fields, then the zero reference. Measure derives the numbering and save
// derives the same one, and nothing passes between them (§3.1).
template <typename Ctx>
inline int64_t RackMessageBodyBits( const Ctx & ctx, const Rack & root, int64_t at, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bits = -1;
    if ( RackNumberFrom( ctx, numbering, root ) )
    {
        const int64_t index_bits = TableBitsRequired( 0, numbering.count + 1 );
        const int64_t table = TableMessageNodeTableMeasure( ctx, numbering, index_bits, at );
        if ( table >= 0 )
        {
            const int64_t body = RackMeasureMessageBody( ctx, numbering, index_bits, at + table, root );
            bits = body < 0 ? -1 : table + body;
        }
    }
    TableNumberingShutdown( numbering );
    return bits;
}

template <typename Ctx>
inline bool RackMessageBodySave( const Ctx & ctx, const Rack & root, TableBitWriter & w, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    bool ok = false;
    if ( RackNumberFrom( ctx, numbering, root ) )
    {
        const int64_t index_bits = TableBitsRequired( 0, numbering.count + 1 );
        ok = TableMessageNodeTableSave( ctx, numbering, index_bits, w ) && RackSaveMessageBody( ctx, numbering, index_bits, w, root );
    }
    TableNumberingShutdown( numbering );
    return ok && !w.overflow;
}

// THE PRIMITIVE IS A BATCH (§3.3): a number of ROOTS in one buffer, one count
// and one continuous bit stream, each body carrying its own numbering. A
// root is a locked region's, `builder.AsConst()`, or a loaded one's. M above
// 256 is a refusal by name, batch_too_large, with nothing written.
inline int64_t RackMeasureMessages( const Rack * const * roots, int64_t count, TableReport * report, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( roots == NULL || count < 1 ) { return -1; }
    if ( count > kTableMessageBatchMax ) { TableMessageRefuseBatch( report ); return -1; }
    TableRegionCtx ctx;
    int64_t bits = 8; // the body count
    for ( int64_t i = 0; i < count; i++ )
    {
        if ( roots[i] == NULL ) { return -1; }
        const int64_t body = RackMessageBodyBits( ctx, *roots[i], bits, allocator );
        if ( body < 0 ) { return -1; }
        bits += body;
    }
    return 1 + ( bits + 7 ) / 8;
}

inline int64_t RackSaveMessages( const Rack * const * roots, int64_t count, uint8_t * buffer, int64_t capacity, TableReport * report, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( roots == NULL || count < 1 ) { return -1; }
    if ( count > kTableMessageBatchMax ) { TableMessageRefuseBatch( report ); return -1; }
    TableMessageBatch batch;
    if ( !TableMessageBatchBegin( batch, buffer, capacity, count ) ) { return -1; }
    TableRegionCtx ctx;
    for ( int64_t i = 0; i < count; i++ )
    {
        if ( roots[i] == NULL || !RackMessageBodySave( ctx, *roots[i], batch.w, allocator ) ) { return -1; }
        batch.written++;
    }
    return TableMessageBatchEnd( batch ); // == RackMeasureMessages( roots, count, report, allocator )
}

// RackMessageRecordScan: one node record's type id and the extent its maps
// take, or a blob's length, the reader left after the record. A type id
// reference of 0, one past E, or one naming anything but a kind-0 entry is
// damage, as §3.1 and §3.3 say.
inline bool RackMessageRecordScan( TableBitReader & r, const TableVocabulary & vocabulary, int64_t index_bits, uint64_t & type_id, int64_t & extent, int64_t & length )
{
    uint64_t type_ref = 0;
    if ( !r.get( type_ref, vocabulary.ref_bits ) ) { return false; }
    TableMessageEntry type_entry;
    if ( !TableMessageNameEntry( vocabulary, type_ref, type_entry ) ) { return false; }
    type_id = type_entry.id;
    extent = 0;
    length = 0;
    if ( type_id == kTableBytesTypeId || type_id == kTableStringTypeId )
    {
        // A BLOB RECORD CARRIES A LENGTH AT THIRTY-TWO RAW BITS, then ALIGNS,
        // then the bytes verbatim (§3.3)
        uint64_t n = 0;
        if ( !r.get( n, 32 ) || !r.align() || !r.skip( (int64_t) n * 8 ) ) { return false; }
        length = (int64_t) n;
        return true;
    }
    return RackNodeMessageExtent( type_id, r, vocabulary, index_bits, extent );
}

// RackMessageBodyStorage: one body's node count and data bytes from the FRAMING
// alone, the reader left at the next body. The node table is walked record
// by record, a table record's body stepped over by its announced shapes and
// a blob's by its length, then the root's own fields. False is a numbering
// that could not be sized; `complete` false is a ROOT body whose own framing
// gave out, which the load meets as damage inside this body after the
// bodies before it were delivered, so the batch is sized through this body
// and no further (§3.3).
inline bool RackMessageBodyStorage( TableBitReader & r, const TableVocabulary & vocabulary, int64_t & records, int64_t & data, bool & complete )
{
    complete = true;
    records = 0;
    data = 0;
    int64_t count = 0;
    if ( !TableMessageNodeTableOpen( r, vocabulary, count ) ) { return false; }
    const int64_t index_bits = TableBitsRequired( 0, count + 1 );
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_id = 0;
        int64_t extent = 0, length = 0;
        if ( !RackMessageRecordScan( r, vocabulary, index_bits, type_id, extent, length ) ) { return false; }
        const int64_t storage = RackNodeMessageStorage( type_id, extent, length );
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
        records++;
    }
    int64_t root_extent = 0;
    if ( !RackMessageExtent( r, vocabulary, index_bits, root_extent ) ) { complete = false; }
    data += TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Rack ) ) + root_extent );
    return true;
}

// RackLoadMeasure's MESSAGE overload: the exact region bytes ONE BATCH needs,
// which is one measurement, one allocation and one bounds check for however
// many bodies ride (§3.3, §6.5). It is a scan by the announced shapes and
// reads no field value. The answer is the data bytes plus the attribution,
// one node directory a body, and -1 for a wire it cannot size: no vocabulary,
// another form, or framing that gives out.
inline int64_t RackLoadMeasure( const TableVocabulary & vocabulary, const uint8_t * buffer, int64_t bytes, int64_t * attribution_bytes = NULL )
{
    TableReport ignored;
    TableMessageBatchReader br;
    const int64_t bodies = TableMessageBatchOpen( br, vocabulary, buffer, bytes, &ignored );
    if ( bodies < 0 ) { return -1; }
    int64_t data = 0, attribution = 0;
    for ( int64_t b = 0; b < bodies; b++ )
    {
        int64_t records = 0, body_data = 0;
        bool complete = true;
        if ( !RackMessageBodyStorage( br.r, vocabulary, records, body_data, complete ) ) { return -1; }
        data += body_data;
        attribution += ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
        if ( !complete ) { break; } // damage inside this body: the load delivers the ones before it
    }
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// RackLoadMessageBodyInto: one body of a batch into the region at `used`. Its
// chunk is the node DIRECTORY, then the records in wire order, then the root
// and the extent its maps take, so every offset a pass needs is known when
// the pass reaches it. PASS ONE fills the numbering from the framing and
// places every node; PASS TWO decodes each record's body into the storage it
// owns; the ROOT's own body decodes last, so every index it carries resolves
// against a numbering already known whole.
inline bool RackLoadMessageBodyInto( TableBitReader & r, const TableVocabulary & vocabulary, TableReport * out, uint8_t * region, int64_t region_bytes, int64_t & used, const Rack * & root_out )
{
    // the node table opens the body, or the body has none
    int64_t count = 0;
    if ( !TableMessageNodeTableOpen( r, vocabulary, count ) ) { out->malformed = true; return false; }
    const int64_t directory_bytes = ( count + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( used + directory_bytes > region_bytes ) { out->malformed = true; return false; }
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + used );
    used += directory_bytes;
    const int64_t index_bits = TableBitsRequired( 0, count + 1 );
    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = directory;
    nodes.count = count + 1;
    nodes.good = false;

    // PASS ONE: the numbering from the framing, every node placed, no body read
    const int64_t records_start = r.offset;
    int32_t unknown_records = 0;
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_id = 0;
        int64_t extent = 0, length = 0;
        if ( !RackMessageRecordScan( r, vocabulary, index_bits, type_id, extent, length ) ) { out->malformed = true; return false; }
        const int64_t storage = RackNodeMessageStorage( type_id, extent, length );
        directory[k + 1].type_id = type_id;
        if ( storage <= 0 )
        {
            // a record whose type id this build cannot name KEEPS ITS INDEX, is
            // counted once here and not once per pointer, and every reference
            // to it reads null (§3.1)
            unknown_records++;
            directory[k + 1].offset = kTableNodeAbsent;
            continue;
        }
        if ( used + storage > region_bytes ) { out->malformed = true; return false; }
        directory[k + 1].offset = (uint64_t) used;
        RackNodePlace( type_id, region + used, length );
        used += storage;
    }
    const int64_t fields_start = r.offset;
    int64_t root_extent = 0;
    {
        TableBitReader walk = r;
        if ( !RackMessageExtent( walk, vocabulary, index_bits, root_extent ) ) { out->malformed = true; return false; }
    }
    const int64_t root_bytes = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Rack ) ) + root_extent );
    if ( used + root_bytes > region_bytes ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) used;
    directory[0].type_id = 0x986d012bd380b0b2ull;
    Rack * root = new ( region + used ) Rack; // lifetime only: LoadMessageBody's first act is RackReset
    RackReset( *root );
    root_out = root;
    TableExtentCarve root_carve;
    root_carve.at = region + used + TableAlignUp64( (int64_t) sizeof( Rack ) );
    root_carve.left = root_extent;
    used += root_bytes;
    nodes.good = true;
    out->unknown += unknown_records;

    // PASS TWO: each record's body into its own storage, in wire order
    r.offset = records_start;
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_ref = 0;
        if ( !r.get( type_ref, vocabulary.ref_bits ) ) { out->malformed = true; return false; }
        const uint64_t type_id = directory[k + 1].type_id;
        if ( type_id == kTableBytesTypeId || type_id == kTableStringTypeId )
        {
            uint64_t length = 0;
            if ( !r.get( length, 32 ) || !r.align() || !r.has( (int64_t) length * 8 ) ) { out->malformed = true; return false; }
            if ( directory[k + 1].offset != kTableNodeAbsent && length > 0 ) { memcpy( region + directory[k + 1].offset + kTableBlobHeader, r.buffer + r.offset / 8, (size_t) length ); }
            r.offset += (int64_t) length * 8;
            continue;
        }
        if ( directory[k + 1].offset == kTableNodeAbsent )
        {
            if ( !TableMessageSkipBody( r, vocabulary, index_bits ) ) { out->malformed = true; return false; }
            continue;
        }
        if ( !RackNodeMessageBody( type_id, r, vocabulary, out, nodes, index_bits, region + directory[k + 1].offset ) ) { return false; }
    }
    if ( r.offset != fields_start ) { out->malformed = true; return false; } // the two passes disagree about the table's extent

    // and the ROOT's own body last
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    return RackLoadMessageBody( r, vocabulary, out, nodes, index_bits, *root );
}

// RackLoadMessages: decode a BATCH into the caller's exact-sized region and
// write each body's root into `roots`. `count` is IN and OUT: the storage the
// caller has room for, then what it got. M above the capacity is a refusal
// by name with count holding the wire's M; damage inside body k delivers
// bodies 1 to k - 1 and count says k - 1 (§3.3). LOAD IS A SCAN: it follows
// no reference, so there is no depth cap and no visited set. NULL roots
// beyond count are not bodies.
inline bool RackLoadMessages( const Rack ** roots, int64_t * count, uint8_t * region, int64_t region_bytes, const TableVocabulary & vocabulary, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    if ( roots == NULL || count == NULL ) { out->malformed = true; return false; }
    const int64_t capacity = *count;
    *count = 0;
    TableMessageBatchReader br;
    const int64_t bodies = TableMessageBatchOpen( br, vocabulary, buffer, bytes, out );
    if ( bodies < 0 ) { return false; }
    if ( bodies > capacity ) { *count = bodies; TableMessageRefuseBatch( out ); return false; }
    if ( region == NULL || region_bytes < 0 || ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return false; }
    memset( region, 0, (size_t) region_bytes );
    int64_t used = 0;
    for ( int64_t b = 0; b < bodies; b++ )
    {
        roots[b] = NULL;
        if ( !RackLoadMessageBodyInto( br.r, vocabulary, out, region, region_bytes, used, roots[b] ) ) { *count = b; return false; }
        br.remaining--;
    }
    *count = bodies;
    return TableMessageBatchClose( br );
}

// RackLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t RackLoadMeasure( const uint8_t * wire_file, int64_t wire_file_bytes, int64_t * attribution_bytes = NULL, TableRefuseReason * reason_out = NULL )
{
    TableReport ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    // a FORM BYTE this build does not carry is refused by name (§3, §6.5);
    // a trailer that cannot be read whole is damage and names no reason
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict == TableOpenRefused ) { if ( reason_out != NULL ) { *reason_out = unknown_form; } return -1; }
    if ( verdict != TableOpenOk ) { return -1; }
    // ANY BYTE BETWEEN THE ROOT'S TERMINATOR AND THE TABLE'S FIRST ENTRY
    // IS MALFORMED (docs/SPEC-TABLES.md §3): the two ends of the file have
    // met, nothing is decoded, and no region is sized from it.
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) ) { return -1; }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    TableRefuseReason reason = count_over_length;
    int64_t root_extent = 0;
    if ( !RackWireExtent( wire, wire_bytes, root_extent, &ids_table, reason ) ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Rack ) ) + root_extent );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = RackNodeStorage( type_id, length, reason );
        if ( storage == kTableNodeRefused ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; } // an N the record's framing cannot carry, or a blob past the cap (§2.8, §2.9, §3.1)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// RackLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Rack * RackLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, then the trailer, and only then a body:
    // a file that is both a newer form and damaged is a REFUSAL and never
    // damage (docs/SPEC-TABLES.md §3).
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; if ( wire_file_bytes > 0 && wire_file[0] == kTableWireMessageForm ) { out->reason = message_form_as_file; } else { out->reason = newer_form; } }
        return NULL;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return NULL;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Rack ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    TableRefuseReason reason = count_over_length; // LoadMeasure is where a caller reads it; a Load past a refusal is malformed
    int64_t root_extent = 0;
    if ( !RackWireExtent( wire, wire_bytes, root_extent, &ids_table, reason ) ) { out->malformed = true; return NULL; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Rack ) ) + root_extent );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = RackNodeStorage( type_id, length, reason );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0x986d012bd380b0b2ull;
    Rack * root = new ( region ) Rack; // lifetime only: LoadBody's first act is RackReset
    RackReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Rack ) ) + root_extent );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = RackNodeStorage( type_id, length, reason );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                RackNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                RackNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableExtentCarve root_carve;
    root_carve.at = region + TableAlignUp64( (int64_t) sizeof( Rack ) );
    root_carve.left = root_extent;
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    RackLoadBody( r, nodes, *root );
    return root;
}

// RackLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool RackLoadBuilder( RackBuilder & builder, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; }
        return false;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return false;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    Rack * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0x986d012bd380b0b2ull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    nodes.worker = &builder.main; // and a map's entries and a list's elements are the arena's, not a node extent's (§2.8, §2.9)
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = RackNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                RackNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableExtentCarve root_carve;
    root_carve.worker = &builder.main;
    nodes.carve = &root_carve;
    bool ok = RackLoadBody( r, nodes, *root );
    // A COUNT ABOVE THE int32 CAP is this path's refusal (docs/SPEC-TABLES.md
    // §2.9): the partial builder is the caller's to discard, and the report
    // holds what it held when the count was met
    ok = ok && !nodes.refused;
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- Tray: the variable-length life (docs/SPEC-TABLES.md §2, §6, §9) ----
//
// MUTABLE: TrayBuilder — allocate nodes, wire them together, then Lock.
// CONST:   one packed region, root at its base. Lock produces it and Load
//          produces it, so a locked structure and a loaded one are the
//          SAME representation with one view API. There is no unlock:
//          re-editing means loading the const form into a fresh builder.
// Tray is never held by value — a file-format-scale structure is a region
// and a root pointer, not a struct you copy.

struct TrayBuilder
{
    TableArena arena;
    TableWorker main;      // the calling thread's allocation front
    TableRef root_ref;
    uint8_t * region = NULL; // the packed const form, produced by Lock()
    int64_t region_bytes = 0;

    // THE ALLOCATOR IS THE BUILDER'S, and everything this structure ever
    // allocates goes through it: the arena's segments, Lock's identity map,
    // the packed region, the wire walks' numbering, and the tool path's node
    // directory. Name your own and a profiler sees every byte under it.
    TrayBuilder( TableAllocator allocator = TableDefaultAllocator() )
    {
        TableArenaInit( arena, allocator );
        main.arena = &arena;
        TableSlot<Tray> slot = main.Alloc<Tray>();
        root_ref = slot.ref;
    }
    ~TrayBuilder() { TableArenaShutdown( arena ); arena.allocator.free( arena.allocator.context, region ); }
    TrayBuilder( const TrayBuilder & ) = delete;
    TrayBuilder & operator=( const TrayBuilder & ) = delete;

    // Alloc a node in THIS thread's slab: no lock, no atomic per node.
    // The result is usable both as the node pointer and as the reference
    // to store in a pointer field.
    template <typename T> TableSlot<T> Alloc() { return main.Alloc<T>(); }
    // a BYTE BUFFER's node of exactly `length` bytes (docs/SPEC-TABLES.md §2.5):
    // the bytes to write through, and the reference to store in a *bytes
    // or *string slot; a blob past a slab takes a span of its own
    TableBytesSlot AllocBytes( int64_t length ) { return main.AllocBytes( length ); }
    TableStringSlot AllocString( int64_t length ) { return main.AllocString( length ); }
    // one worker per thread; allocate on your own, and synchronize your own
    // writes to nodes another worker allocated
    TableWorker Worker() { TableWorker worker; worker.arena = &arena; return worker; }

    // GetRoot/AsConst, not Root/Const: a member function hides the type
    // name it shares, and `table Root` is this spec's own canonical
    // example. The checker refuses a table named after any member here,
    // so the remaining spellings cannot collide either.
    Tray * GetRoot() { return arena.locked ? NULL : (Tray *) TableArenaAt( arena, (uint32_t) root_ref.value ); }
    bool Locked() const { return arena.locked; }
    const Tray * AsConst() const { return (const Tray *) region; }
    const uint8_t * Region() const { return region; }
    int64_t RegionBytes() const { return region_bytes; }

    // Lock is ONE WAY and it is the compaction: the segmented arena becomes
    // one exact-packed region with zero slack, references rewritten
    // self-relative, and the mutable life released. Single-threaded: call
    // it after the workers have joined.
    bool Lock();
};

inline bool TrayBuilder::Lock()
{
    if ( arena.locked ) { return region != NULL; }
    if ( root_ref.null() ) { return false; }
    TableArenaCtx ctx = { &arena };
    const Tray & root = *(const Tray *) TableArenaAt( arena, (uint32_t) root_ref.value );
    // The ROOT takes the map's first entry: it is packed at offset 0, and its
    // descent is open for the whole walk (docs/SPEC-TABLES.md §3.1).
    TablePackMap seen;
    TablePackMapInit( seen, arena.allocator );
    bool root_taken = false;
    int64_t root_slot = 0;
    int64_t below = -1;
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) != NULL )
    {
        below = TrayPackMeasure( ctx, seen, root );
    }
    if ( below < 0 ) { TablePackMapShutdown( seen ); return false; } // a data cycle, named at the reference that closes it
    int64_t root_extent = TrayExtent( ctx, root );
    if ( root_extent < 0 ) { TablePackMapShutdown( seen ); return false; } // the sort could not run
    int64_t total = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Tray ) ) + root_extent ) + below;
    // the AUTHORING path may allocate (§6.5), and it does so through the
    // builder's own pair. The region comes back ZEROED, which is the
    // allocator's contract: a packed region carries node padding.
    uint8_t * packed = (uint8_t *) arena.allocator.alloc( arena.allocator.context, total );
    if ( packed == NULL ) { TablePackMapShutdown( seen ); return false; }
    int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Tray ) ) + root_extent );
    Tray * destination = new ( packed ) Tray; // lifetime only: the Pack below memcpy's the whole node over it
    // The pack walk RE-DERIVES the same numbering rather than carrying the
    // measure's — nothing passes between them, which is what makes
    // `used == total` below a real check and not a tautology (§3.1). The
    // map keeps the capacity the measure paid for, so the second walk
    // rehashes nothing.
    TablePackMapReset( seen );
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) == NULL ||
         !TrayPack( ctx, seen, root, *destination, packed, total, used ) || used != total )
    {
        TablePackMapShutdown( seen );
        arena.allocator.free( arena.allocator.context, packed );
        return false;
    }
    TablePackMapShutdown( seen );
    region = packed;
    region_bytes = total;
    arena.locked = true; // MONOTONIC: there is no unlock
    TableArenaShutdown( arena );
    return true;
}

// ---- Tray on the wire: the FLAT NODE TABLE (docs/SPEC-TABLES.md §3.1) ----
//
// A pointered save writes every reachable node ONCE, into a node table under
// the reserved id 0xFFFF, and a pointer field rides as a u32 INDEX into it
// under kind 17. No pointer edge is a nesting level, so a chain's length is
// not a depth and two references to one node are one node.

// TrayNodeStorage: the region bytes one record commands, or -1 for a type id
// this build cannot name — which keeps its index and reads null. A BYTE
// BUFFER's record commands its header and its bytes (docs/SPEC-TABLES.md §2.5),
// which is the one answer the record's LENGTH decides, and a blob past the
// size cap answers kTableNodeRefused with its reason (§3.1, §6.5).
// A MAP'S ENTRIES RIDE IN THEIR HOLDER'S EXTENT (docs/SPEC-TABLES.md §2.8),
// so a record's storage is its type's PLUS N x sizeof( Entry ) at every
// depth, summed from the FRAMING: N is framing and not a value, and this
// reads no field. kTableNodeRefused is a wire whose N its L cannot carry.
inline int64_t TrayNodeStorage( uint64_t type_id, int64_t length, TableRefuseReason & reason )
{
    (void) length; // no byte buffer below this root: every node's storage is its type's
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( (int64_t) sizeof( Node ) ); // Node
        default: break;
    }
    (void) reason; // no blob and no extent below this root: nothing here refuses
    return -1;
}

// TrayNodePlace: start one record's node's lifetime in the storage pass one
// reserved for it, holding exactly the declared defaults — a byte buffer's
// header holds its length, and its bytes come in pass two.
inline void TrayNodePlace( uint64_t type_id, uint8_t * at, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: { Node * node = new ( at ) Node; NodeReset( *node ); break; } // Node
        default: break;
    }
}

// TrayNodeRecordBytes: one record's OWN storage, before the extent its maps
// take (docs/SPEC-TABLES.md §2.8) — where a node's extent begins.
inline int64_t TrayNodeRecordBytes( uint64_t type_id )
{
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( (int64_t) sizeof( Node ) ); // Node
        default: break;
    }
    return 0;
}

// TrayNodeAlloc: the TOOL's path — one record's node in the builder's arena.
// Zero is the arena's null, and it is also what a type id this build cannot
// name answers.
inline uint32_t TrayNodeAlloc( uint64_t type_id, TableWorker & worker, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return (uint32_t) worker.Alloc<Node>().ref.value; // Node
        default: break;
    }
    return 0;
}

// TrayNodeBody: PASS TWO's half — decode one record's body into the storage it
// already owns.
inline void TrayNodeBody( uint64_t type_id, TableReader & r, const TableNodeMap & nodes, uint8_t * at )
{
    // the node's own EXTENT, where its lists' and maps' arrays are carved
    // from, PRE-ORDER as the bodies decode (docs/SPEC-TABLES.md §2.8, §2.9).
    // The tool's path carries a worker instead: there the arrays are the
    // arena's.
    TableExtentCarve carve;
    carve.worker = nodes.worker;
    if ( carve.worker == NULL )
    {
        TableRefuseReason reason = count_over_length; // pass one already refused what this could refuse
        const int64_t storage = TrayNodeStorage( type_id, r.size, reason );
        const int64_t record = storage > 0 ? TrayNodeRecordBytes( type_id ) : 0;
        carve.at = at + record;
        carve.left = storage > record ? storage - record : 0;
    }
    nodes.carve = &carve;
    (void) nodes; // every node this root can name is a FIXED table
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: NodeLoadBody( r, *(Node *) at ); break; // Node
        default: break;
    }
    nodes.carve = NULL; // the cursor is ONE node's, and this node's body is done
}

// TrayNodeMessageStorage: the region bytes one record commands on the message
// wire, or -1 for a type id this build cannot name. A table's is its own
// storage plus the extent its maps take; a byte buffer's is its header and
// its bytes, which is the one answer the record's LENGTH decides.
inline int64_t TrayNodeMessageStorage( uint64_t type_id, int64_t extent, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: return TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Node ) ) + extent ); // Node
        default: break;
    }
    return -1;
}

// TrayNodeMessageExtent: step over one TABLE record's body, tallying the extent
// its maps take where its type has any (§2.8). A type this build cannot
// name is stepped over by its announced shapes and takes no extent.
inline bool TrayNodeMessageExtent( uint64_t type_id, TableBitReader & r, const TableVocabulary & vocabulary, int64_t index_bits, int64_t & extent )
{
    extent = 0;
    (void) type_id; // no map below any node this root can name
    return TableMessageSkipBody( r, vocabulary, index_bits );
}

// TrayNodeMessageBody: PASS TWO's half, which decodes one record's body into
// storage it already owns, its map entries carved from its own extent.
inline bool TrayNodeMessageBody( uint64_t type_id, TableBitReader & r, const TableVocabulary & vocabulary, TableReport * report, const TableNodeMap & nodes, int64_t index_bits, uint8_t * at )
{
    TableExtentCarve carve;
    carve.at = at + TrayNodeRecordBytes( type_id );
    carve.left = 0;
    {
        // the extent this record was placed with, re-read from the framing
        TableBitReader walk = r;
        int64_t extent = 0;
        if ( !TrayNodeMessageExtent( type_id, walk, vocabulary, index_bits, extent ) ) { report->malformed = true; return false; }
        carve.left = extent;
    }
    TableExtentCarve * const outer = nodes.carve;
    nodes.carve = &carve;
    (void) nodes; (void) index_bits; // every node this root can name is a FIXED table
    bool ok = false;
    switch ( type_id )
    {
        case 0x66bd1cc6d2f6b68dull: ok = NodeLoadMessageBody( r, vocabulary, report, index_bits, *(Node *) at ); break; // Node
        // a record this dispatch cannot name never reaches here: pass one left it absent
        default: report->malformed = true; break;
    }
    nodes.carve = outer;
    return ok;
}

// The numbering both wire walks derive, and NEITHER CARRIES THE OTHER'S: the
// root takes index 1 and its entry stays open for the whole walk, so a
// reference back at it is the cycle it is (§3.1).
template <typename Ctx>
inline bool TrayNumberFrom( const Ctx & ctx, TableNumbering & numbering, const Tray & root )
{
    bool taken = false;
    int64_t slot = 0;
    if ( TablePackMapReach( numbering.seen, (const void *) &root, (int64_t) kTableNodeIndexRoot, taken, slot ) == NULL ) { return false; }
    return TrayNumber( ctx, numbering, root );
}

template <typename Ctx>
inline int64_t TrayMeasureWire( const Ctx & ctx, const Tray & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bytes = -1;
    if ( TrayNumberFrom( ctx, numbering, root ) )
    {
        TableIds ids;
        bytes = TrayMeasureBody( ctx, numbering, ids, root );
        if ( bytes >= 0 )
        {
            const int64_t table = TableNodeTableMeasure( ctx, ids, numbering );
            // the FORM BYTE, the ROOT BODY — its own fields, the node table
            // and the terminator — and the ID TABLE (docs/SPEC-TABLES.md §3)
            bytes = table < 0 || ids.overflow ? -1 : 1 + bytes + table + TableIdsBytes( ids );
        }
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

template <typename Ctx>
inline int64_t TraySaveWire( const Ctx & ctx, const Tray & root, uint8_t * buffer, int64_t capacity, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    if ( !TrayNumberFrom( ctx, numbering, root ) ) { TableNumberingShutdown( numbering ); return -1; }
    TableWriter w( buffer, capacity );
    TableIds ids;
    w.put8( kTableWireForm ); // the FORM BYTE is the whole header (§3)
    // the root's own fields, then the node table's field, then the
    // terminator: a reader that gives up inside the table has already
    // decoded the ROOT'S OWN FIELDS (§3.1)
    bool ok = TraySaveBodyFields( ctx, numbering, w, ids, root ) && TableNodeTableSave( ctx, w, ids, numbering );
    TableNumberingShutdown( numbering );
    if ( !ok || ids.overflow ) { return -1; }
    w.put8( 0 ); // the ZERO REFERENCE that ends the root body
    TableIdsWrite( w, ids );
    if ( w.overflow ) { return -1; } // the caller's buffer was too small
    return w.offset; // == TrayMeasure( root )
}

inline int64_t TrayMeasure( const Tray * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return TrayMeasureWire( ctx, *root, allocator );
}

inline int64_t TraySave( const Tray * root, uint8_t * buffer, int64_t capacity, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return TraySaveWire( ctx, *root, buffer, capacity, allocator );
}

inline int64_t TrayMeasure( const TrayBuilder & builder )
{
    if ( builder.region != NULL ) { return TrayMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return TrayMeasureWire( ctx, *(const Tray *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline int64_t TraySave( const TrayBuilder & builder, uint8_t * buffer, int64_t capacity )
{
    if ( builder.region != NULL ) { return TraySave( builder.AsConst(), buffer, capacity, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return TraySaveWire( ctx, *(const Tray *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), buffer, capacity, builder.arena.allocator );
}

// ---- Tray on the MESSAGE wire: the batch over a region (docs/SPEC-TABLES.md §3.3) ----

// TrayMessageBodyBits: one root body's bits at bit position `at` of the batch,
// with the numbering derived from the graph, the node table FIRST, then the
// fields, then the zero reference. Measure derives the numbering and save
// derives the same one, and nothing passes between them (§3.1).
template <typename Ctx>
inline int64_t TrayMessageBodyBits( const Ctx & ctx, const Tray & root, int64_t at, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bits = -1;
    if ( TrayNumberFrom( ctx, numbering, root ) )
    {
        const int64_t index_bits = TableBitsRequired( 0, numbering.count + 1 );
        const int64_t table = TableMessageNodeTableMeasure( ctx, numbering, index_bits, at );
        if ( table >= 0 )
        {
            const int64_t body = TrayMeasureMessageBody( ctx, numbering, index_bits, at + table, root );
            bits = body < 0 ? -1 : table + body;
        }
    }
    TableNumberingShutdown( numbering );
    return bits;
}

template <typename Ctx>
inline bool TrayMessageBodySave( const Ctx & ctx, const Tray & root, TableBitWriter & w, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    bool ok = false;
    if ( TrayNumberFrom( ctx, numbering, root ) )
    {
        const int64_t index_bits = TableBitsRequired( 0, numbering.count + 1 );
        ok = TableMessageNodeTableSave( ctx, numbering, index_bits, w ) && TraySaveMessageBody( ctx, numbering, index_bits, w, root );
    }
    TableNumberingShutdown( numbering );
    return ok && !w.overflow;
}

// THE PRIMITIVE IS A BATCH (§3.3): a number of ROOTS in one buffer, one count
// and one continuous bit stream, each body carrying its own numbering. A
// root is a locked region's, `builder.AsConst()`, or a loaded one's. M above
// 256 is a refusal by name, batch_too_large, with nothing written.
inline int64_t TrayMeasureMessages( const Tray * const * roots, int64_t count, TableReport * report, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( roots == NULL || count < 1 ) { return -1; }
    if ( count > kTableMessageBatchMax ) { TableMessageRefuseBatch( report ); return -1; }
    TableRegionCtx ctx;
    int64_t bits = 8; // the body count
    for ( int64_t i = 0; i < count; i++ )
    {
        if ( roots[i] == NULL ) { return -1; }
        const int64_t body = TrayMessageBodyBits( ctx, *roots[i], bits, allocator );
        if ( body < 0 ) { return -1; }
        bits += body;
    }
    return 1 + ( bits + 7 ) / 8;
}

inline int64_t TraySaveMessages( const Tray * const * roots, int64_t count, uint8_t * buffer, int64_t capacity, TableReport * report, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( roots == NULL || count < 1 ) { return -1; }
    if ( count > kTableMessageBatchMax ) { TableMessageRefuseBatch( report ); return -1; }
    TableMessageBatch batch;
    if ( !TableMessageBatchBegin( batch, buffer, capacity, count ) ) { return -1; }
    TableRegionCtx ctx;
    for ( int64_t i = 0; i < count; i++ )
    {
        if ( roots[i] == NULL || !TrayMessageBodySave( ctx, *roots[i], batch.w, allocator ) ) { return -1; }
        batch.written++;
    }
    return TableMessageBatchEnd( batch ); // == TrayMeasureMessages( roots, count, report, allocator )
}

// TrayMessageRecordScan: one node record's type id and the extent its maps
// take, or a blob's length, the reader left after the record. A type id
// reference of 0, one past E, or one naming anything but a kind-0 entry is
// damage, as §3.1 and §3.3 say.
inline bool TrayMessageRecordScan( TableBitReader & r, const TableVocabulary & vocabulary, int64_t index_bits, uint64_t & type_id, int64_t & extent, int64_t & length )
{
    uint64_t type_ref = 0;
    if ( !r.get( type_ref, vocabulary.ref_bits ) ) { return false; }
    TableMessageEntry type_entry;
    if ( !TableMessageNameEntry( vocabulary, type_ref, type_entry ) ) { return false; }
    type_id = type_entry.id;
    extent = 0;
    length = 0;
    if ( type_id == kTableBytesTypeId || type_id == kTableStringTypeId )
    {
        // A BLOB RECORD CARRIES A LENGTH AT THIRTY-TWO RAW BITS, then ALIGNS,
        // then the bytes verbatim (§3.3)
        uint64_t n = 0;
        if ( !r.get( n, 32 ) || !r.align() || !r.skip( (int64_t) n * 8 ) ) { return false; }
        length = (int64_t) n;
        return true;
    }
    return TrayNodeMessageExtent( type_id, r, vocabulary, index_bits, extent );
}

// TrayMessageBodyStorage: one body's node count and data bytes from the FRAMING
// alone, the reader left at the next body. The node table is walked record
// by record, a table record's body stepped over by its announced shapes and
// a blob's by its length, then the root's own fields. False is a numbering
// that could not be sized; `complete` false is a ROOT body whose own framing
// gave out, which the load meets as damage inside this body after the
// bodies before it were delivered, so the batch is sized through this body
// and no further (§3.3).
inline bool TrayMessageBodyStorage( TableBitReader & r, const TableVocabulary & vocabulary, int64_t & records, int64_t & data, bool & complete )
{
    complete = true;
    records = 0;
    data = 0;
    int64_t count = 0;
    if ( !TableMessageNodeTableOpen( r, vocabulary, count ) ) { return false; }
    const int64_t index_bits = TableBitsRequired( 0, count + 1 );
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_id = 0;
        int64_t extent = 0, length = 0;
        if ( !TrayMessageRecordScan( r, vocabulary, index_bits, type_id, extent, length ) ) { return false; }
        const int64_t storage = TrayNodeMessageStorage( type_id, extent, length );
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
        records++;
    }
    int64_t root_extent = 0;
    if ( !TableMessageSkipBody( r, vocabulary, index_bits ) ) { complete = false; }
    data += TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Tray ) ) + root_extent );
    return true;
}

// TrayLoadMeasure's MESSAGE overload: the exact region bytes ONE BATCH needs,
// which is one measurement, one allocation and one bounds check for however
// many bodies ride (§3.3, §6.5). It is a scan by the announced shapes and
// reads no field value. The answer is the data bytes plus the attribution,
// one node directory a body, and -1 for a wire it cannot size: no vocabulary,
// another form, or framing that gives out.
inline int64_t TrayLoadMeasure( const TableVocabulary & vocabulary, const uint8_t * buffer, int64_t bytes, int64_t * attribution_bytes = NULL )
{
    TableReport ignored;
    TableMessageBatchReader br;
    const int64_t bodies = TableMessageBatchOpen( br, vocabulary, buffer, bytes, &ignored );
    if ( bodies < 0 ) { return -1; }
    int64_t data = 0, attribution = 0;
    for ( int64_t b = 0; b < bodies; b++ )
    {
        int64_t records = 0, body_data = 0;
        bool complete = true;
        if ( !TrayMessageBodyStorage( br.r, vocabulary, records, body_data, complete ) ) { return -1; }
        data += body_data;
        attribution += ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
        if ( !complete ) { break; } // damage inside this body: the load delivers the ones before it
    }
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// TrayLoadMessageBodyInto: one body of a batch into the region at `used`. Its
// chunk is the node DIRECTORY, then the records in wire order, then the root
// and the extent its maps take, so every offset a pass needs is known when
// the pass reaches it. PASS ONE fills the numbering from the framing and
// places every node; PASS TWO decodes each record's body into the storage it
// owns; the ROOT's own body decodes last, so every index it carries resolves
// against a numbering already known whole.
inline bool TrayLoadMessageBodyInto( TableBitReader & r, const TableVocabulary & vocabulary, TableReport * out, uint8_t * region, int64_t region_bytes, int64_t & used, const Tray * & root_out )
{
    // the node table opens the body, or the body has none
    int64_t count = 0;
    if ( !TableMessageNodeTableOpen( r, vocabulary, count ) ) { out->malformed = true; return false; }
    const int64_t directory_bytes = ( count + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( used + directory_bytes > region_bytes ) { out->malformed = true; return false; }
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + used );
    used += directory_bytes;
    const int64_t index_bits = TableBitsRequired( 0, count + 1 );
    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = directory;
    nodes.count = count + 1;
    nodes.good = false;

    // PASS ONE: the numbering from the framing, every node placed, no body read
    const int64_t records_start = r.offset;
    int32_t unknown_records = 0;
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_id = 0;
        int64_t extent = 0, length = 0;
        if ( !TrayMessageRecordScan( r, vocabulary, index_bits, type_id, extent, length ) ) { out->malformed = true; return false; }
        const int64_t storage = TrayNodeMessageStorage( type_id, extent, length );
        directory[k + 1].type_id = type_id;
        if ( storage <= 0 )
        {
            // a record whose type id this build cannot name KEEPS ITS INDEX, is
            // counted once here and not once per pointer, and every reference
            // to it reads null (§3.1)
            unknown_records++;
            directory[k + 1].offset = kTableNodeAbsent;
            continue;
        }
        if ( used + storage > region_bytes ) { out->malformed = true; return false; }
        directory[k + 1].offset = (uint64_t) used;
        TrayNodePlace( type_id, region + used, length );
        used += storage;
    }
    const int64_t fields_start = r.offset;
    int64_t root_extent = 0;
    const int64_t root_bytes = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Tray ) ) + root_extent );
    if ( used + root_bytes > region_bytes ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) used;
    directory[0].type_id = 0x85a6b5fb5284964dull;
    Tray * root = new ( region + used ) Tray; // lifetime only: LoadMessageBody's first act is TrayReset
    TrayReset( *root );
    root_out = root;
    TableExtentCarve root_carve;
    root_carve.at = region + used + TableAlignUp64( (int64_t) sizeof( Tray ) );
    root_carve.left = root_extent;
    used += root_bytes;
    nodes.good = true;
    out->unknown += unknown_records;

    // PASS TWO: each record's body into its own storage, in wire order
    r.offset = records_start;
    for ( int64_t k = 0; k < count; k++ )
    {
        uint64_t type_ref = 0;
        if ( !r.get( type_ref, vocabulary.ref_bits ) ) { out->malformed = true; return false; }
        const uint64_t type_id = directory[k + 1].type_id;
        if ( type_id == kTableBytesTypeId || type_id == kTableStringTypeId )
        {
            uint64_t length = 0;
            if ( !r.get( length, 32 ) || !r.align() || !r.has( (int64_t) length * 8 ) ) { out->malformed = true; return false; }
            if ( directory[k + 1].offset != kTableNodeAbsent && length > 0 ) { memcpy( region + directory[k + 1].offset + kTableBlobHeader, r.buffer + r.offset / 8, (size_t) length ); }
            r.offset += (int64_t) length * 8;
            continue;
        }
        if ( directory[k + 1].offset == kTableNodeAbsent )
        {
            if ( !TableMessageSkipBody( r, vocabulary, index_bits ) ) { out->malformed = true; return false; }
            continue;
        }
        if ( !TrayNodeMessageBody( type_id, r, vocabulary, out, nodes, index_bits, region + directory[k + 1].offset ) ) { return false; }
    }
    if ( r.offset != fields_start ) { out->malformed = true; return false; } // the two passes disagree about the table's extent

    // and the ROOT's own body last
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    return TrayLoadMessageBody( r, vocabulary, out, nodes, index_bits, *root );
}

// TrayLoadMessages: decode a BATCH into the caller's exact-sized region and
// write each body's root into `roots`. `count` is IN and OUT: the storage the
// caller has room for, then what it got. M above the capacity is a refusal
// by name with count holding the wire's M; damage inside body k delivers
// bodies 1 to k - 1 and count says k - 1 (§3.3). LOAD IS A SCAN: it follows
// no reference, so there is no depth cap and no visited set. NULL roots
// beyond count are not bodies.
inline bool TrayLoadMessages( const Tray ** roots, int64_t * count, uint8_t * region, int64_t region_bytes, const TableVocabulary & vocabulary, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    if ( roots == NULL || count == NULL ) { out->malformed = true; return false; }
    const int64_t capacity = *count;
    *count = 0;
    TableMessageBatchReader br;
    const int64_t bodies = TableMessageBatchOpen( br, vocabulary, buffer, bytes, out );
    if ( bodies < 0 ) { return false; }
    if ( bodies > capacity ) { *count = bodies; TableMessageRefuseBatch( out ); return false; }
    if ( region == NULL || region_bytes < 0 || ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return false; }
    memset( region, 0, (size_t) region_bytes );
    int64_t used = 0;
    for ( int64_t b = 0; b < bodies; b++ )
    {
        roots[b] = NULL;
        if ( !TrayLoadMessageBodyInto( br.r, vocabulary, out, region, region_bytes, used, roots[b] ) ) { *count = b; return false; }
        br.remaining--;
    }
    *count = bodies;
    return TableMessageBatchClose( br );
}

// TrayLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t TrayLoadMeasure( const uint8_t * wire_file, int64_t wire_file_bytes, int64_t * attribution_bytes = NULL, TableRefuseReason * reason_out = NULL )
{
    TableReport ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    // a FORM BYTE this build does not carry is refused by name (§3, §6.5);
    // a trailer that cannot be read whole is damage and names no reason
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict == TableOpenRefused ) { if ( reason_out != NULL ) { *reason_out = unknown_form; } return -1; }
    if ( verdict != TableOpenOk ) { return -1; }
    // ANY BYTE BETWEEN THE ROOT'S TERMINATOR AND THE TABLE'S FIRST ENTRY
    // IS MALFORMED (docs/SPEC-TABLES.md §3): the two ends of the file have
    // met, nothing is decoded, and no region is sized from it.
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) ) { return -1; }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    TableRefuseReason reason = count_over_length;
    int64_t root_extent = 0;
    if ( !TrayWireExtent( wire, wire_bytes, root_extent, &ids_table, reason ) ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Tray ) ) + root_extent );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = TrayNodeStorage( type_id, length, reason );
        if ( storage == kTableNodeRefused ) { if ( reason_out != NULL ) { *reason_out = reason; } return -1; } // an N the record's framing cannot carry, or a blob past the cap (§2.8, §2.9, §3.1)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// TrayLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Tray * TrayLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, then the trailer, and only then a body:
    // a file that is both a newer form and damaged is a REFUSAL and never
    // damage (docs/SPEC-TABLES.md §3).
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; if ( wire_file_bytes > 0 && wire_file[0] == kTableWireMessageForm ) { out->reason = message_form_as_file; } else { out->reason = newer_form; } }
        return NULL;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return NULL;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Tray ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    TableRefuseReason reason = count_over_length; // LoadMeasure is where a caller reads it; a Load past a refusal is malformed
    int64_t root_extent = 0;
    if ( !TrayWireExtent( wire, wire_bytes, root_extent, &ids_table, reason ) ) { out->malformed = true; return NULL; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Tray ) ) + root_extent );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = TrayNodeStorage( type_id, length, reason );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0x85a6b5fb5284964dull;
    Tray * root = new ( region ) Tray; // lifetime only: LoadBody's first act is TrayReset
    TrayReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Tray ) ) + root_extent );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = TrayNodeStorage( type_id, length, reason );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                TrayNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                TrayNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableExtentCarve root_carve;
    root_carve.at = region + TableAlignUp64( (int64_t) sizeof( Tray ) );
    root_carve.left = root_extent;
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    TrayLoadBody( r, nodes, *root );
    return root;
}

// TrayLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool TrayLoadBuilder( TrayBuilder & builder, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; }
        return false;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return false;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    Tray * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0x85a6b5fb5284964dull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    nodes.worker = &builder.main; // and a map's entries and a list's elements are the arena's, not a node extent's (§2.8, §2.9)
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = TrayNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                TrayNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableExtentCarve root_carve;
    root_carve.worker = &builder.main;
    nodes.carve = &root_carve;
    bool ok = TrayLoadBody( r, nodes, *root );
    // A COUNT ABOVE THE int32 CAP is this path's refusal (docs/SPEC-TABLES.md
    // §2.9): the partial builder is the caller's to discard, and the report
    // holds what it held when the count was met
    ok = ok && !nodes.refused;
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- the cooked form: point at a cook (docs/SPEC-TABLES.md §7) ----

// NodeOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and NAMES the refusal in the caller's
// TableRefuseReason, the first failing clause in §7's order (a wrong build
// version is a re-cook, a foreign order a cross-endian cook, a truncated
// file a bad download, an unaligned base the caller's own buffer), and the
// caller falls back to a wire load, which is the path that carries every
// version. The reason is written on the refusal path only; a caller that
// passes nothing gets the null alone.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// Node IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Node * NodeOpen( const void * bytes, uint64_t length, TableRefuseReason * reason = NULL )
{
    return (const Node *) TableCookOpen( bytes, length, (uint64_t) sizeof( Node ), (uint64_t) alignof( Node ), reason );
}

